    $events = $this->db->fetchAllAssociative("SELECT id, ts, tokens_input,...,cost_usd FROM usage_events WHERE provider_code=? AND model_code=? AND status='rated'", ...);
    $offPeak = $this->db->fetchAssociative('SELECT off_peak_window_start, off_peak_window_end, off_peak_multiplier FROM providers WHERE code = ?', [$provider]);
    $count = 0; $delta = '0';
    foreach ($events as $e) {
        $applicable = null;
        foreach ($rows as $r) {
            if ($r['valid_from'] <= $e['ts'] as strings ... hmm, string comparison works for 'Y-m-d H:i:s' (lexicographic = chronological).
            applicable = last row where valid_from <= ts.
        }
        if ($applicable === null) continue;
        if (!isset($touchedIds[(int)$applicable['id']])) continue;
        $ts = new DateTimeImmutable($e['ts']); // string 'Y-m-d H:i:s' + UTC
        $newCost = $this->calculator->cost(int $e['tokens_input'], int $e['tokens_output'], int $e['tokens_cache_read'], int $e['tokens_cache_write'], [
            'unit' => $applicable['unit'],
            'input' => (string)($applicable['rate_input'] ?? '0'? no — null → string cast? For per_1m, all four rates must be set. Cast to string: (string)$applicable['rate_input'],
