        ], $offPeak === false ? null : ['start'=>..., 'end'=>..., 'multiplier'=>(string)$offPeak['off_peak_multiplier']], $ts);
        $old = bc: (string)$e['cost_usd'];
        $delta = bcadd($delta, bcsub($newCost, (string)$e['cost_usd'], 16), 16);
